macro_rules! comment_submodule_workspaces {
    () => {
        pub fn comment_submodule_workspaces (root_dir : & Path , dry_run : bool , executor : Arc < dyn Execv + Send + Sync > ,) -> anyhow :: Result < () > { println ! ("Commenting out [workspace] sections in submodule Cargo.toml files...") ; let submodules_dir = root_dir . join ("submodules") ; for entry in walkdir :: WalkDir :: new (& submodules_dir) . into_iter () . filter_map (| e | e . ok ()) . filter (| e | e . file_type () . is_file () && e . file_name () == "Cargo.toml") { let cargo_toml_path = entry . path () ; println ! ("Processing Cargo.toml: {:?}" , cargo_toml_path) ; println ! ("  Dry run: {}" , dry_run) ; let mut doc = fs :: read_to_string (& cargo_toml_path) ? . parse :: < toml_edit :: DocumentMut > () ? ; if let Some (workspace_item) = doc . get_mut ("workspace") { if dry_run { println ! ("--- DRY RUN: Would remove [workspace] section in {:?} ---" , cargo_toml_path) ; } else { doc . remove ("workspace") ; println ! ("  Removed [workspace] section from {:?}" , cargo_toml_path) ; } } else { println ! ("  No [workspace] section found in {:?}" , cargo_toml_path) ; } if dry_run { println ! ("--- DRY RUN: Generated Cargo.toml content for {:?} ---" , cargo_toml_path) ; println ! ("{}" , doc . to_string ()) ; println ! ("---------------------------------------------") ; } else { fs :: write (& cargo_toml_path , doc . to_string ()) ? ; println ! ("Successfully updated Cargo.toml: {:?}" , cargo_toml_path) ; } } println ! ("Finished commenting out [workspace] sections.") ; Ok (()) }
    };
}

comment_submodule_workspaces!();